function setUpgradeSubmenuTargetBlank(){const e=document.querySelector("#toplevel_page_gutena-forms ul li:last-child a");e&&"Upgrade"===e.innerText&&e.setAttribute("target","_blank")}document.addEventListener("DOMContentLoaded",function(){new class{constructor(){"undefined"!=typeof gutenaFormsAdminNotice&&null!==gutenaFormsAdminNotice&&""!==gutenaFormsAdminNotice&&this.dismissAdminNotice()}isEmpty(e){return null==e||""===e}getParents(e,t){let n=[];for(;e&&e.parentNode!==document.body;)e.matches(t)&&n.push(e),e=e.parentNode;return 0<n.length&&n[0]}dismissAdminNotice(){document.addEventListener("click",e=>{const t=e.target.closest(".gutena-forms-admin-notice .notice-dismiss");if(!t)return;const n=this.getParents(t,".gutena-forms-admin-notice");if(this.isEmpty(n))return;const o=n.getAttribute("id");fetch(gutenaFormsAdminNotice.ajax_url,{method:"POST",credentials:"same-origin",headers:{"Content-Type":"application/x-www-form-urlencoded",Accept:"application/json"},body:new URLSearchParams({action:gutenaFormsAdminNotice.dismiss_notice_action,gfnonce:gutenaFormsAdminNotice.nonce,notice_id:o})}).then(e=>e.json()).then(()=>{n.remove()}).catch(e=>{console.error("Error:",e)})})}},setUpgradeSubmenuTargetBlank()});